(i) => {
 const s=i.state || {yaw:0,pitch:0,hp:100,ammo:18,reload:0,nextShot:0,dry:0,kills:0,hit:0,damage:0,won:false,droneHp:{},charge:0,ui:{},cues:[]};
 const c=[];
 // Spawned effects join the world at the end of the tick, so their sound cue goes out on the next one.
 const cue=(event,tag)=>s.cues.push([i.tick+1,event,tag]);
 for(const [t,event,tag] of s.cues){if(t===i.tick){c.push({kind:'emit',event,target:{tag}});}}
 s.cues=s.cues.filter(([t])=>t>i.tick);
 const up=(x,y,z)=>{const w=1+y,l=Math.hypot(z,w,x)||1;return w<1e-6?[1,0,0,0]:[z/l,0,-x/l,w/l];};
 s.yaw-=i.look.x*0.002;s.pitch=Math.max(-1.3,Math.min(1.3,s.pitch-i.look.y*0.002));
 if(i.tick===0){return {state:s,commands:[]};}
 const hurt=()=>{s.hp=Math.max(0,s.hp-10);s.damage=i.tick+15;c.push({kind:'emit',event:'hurt'});};
 for(const e of i.events){if(e.kind==='trigger'&&e.event==='damage'&&s.hp>0&&!s.won){hurt();}}
 for(const q of i.queries){
  if(q.queryId!=='rifle'){continue;}
  if(q.position){const n=q.normal||{x:0,y:1,z:0};c.push({kind:'spawn',prefabId:'impact',position:{x:q.position.x+n.x*0.02,y:q.position.y+n.y*0.02,z:q.position.z+n.z*0.02},rotation:up(n.x,n.y,n.z)});}
  if(q.entityId&&q.entityId.startsWith('drone-')){
   s.droneHp[q.entityId]=(s.droneHp[q.entityId]===undefined?3:s.droneHp[q.entityId])-1;s.hit=i.tick+8;c.push({kind:'emit',event:'hit'});
   if(s.droneHp[q.entityId]===0){
    s.kills++;const d=world.get(q.entityId);
    if(d){c.push({kind:'spawn',prefabId:'explosion',position:{x:d.position.x,y:d.position.y,z:d.position.z}});cue('boom','explosion');}
    c.push({kind:'despawn',entityId:q.entityId},{kind:'emit',event:'destroyed'});
   }
  }
 }
 for(const q of i.queries){if(q.queryId==='enemy-fire'&&!q.entityId&&s.hp>0&&!s.won){hurt();}}
 if(s.hp>0&&!s.won&&(i.entity.position.z<4||s.ammo<18)){
  const index=Math.floor(i.tick/90)%5,enemy=world.get('drone-'+index);
  if(enemy&&enemy.active!==false){const p=i.entity.position,e=enemy.position,dx=p.x-e.x,dy=p.y+0.4-e.y,dz=p.z-e.z,dist=Math.hypot(dx,dy,dz);
   if(dist<20&&i.tick%90===50){s.charge=i.tick+40;c.push({kind:'spawn',prefabId:'drone-charge',position:{x:e.x+dx/dist,y:e.y+dy/dist,z:e.z+dz/dist}});cue('charge','drone-charge');}
   if(dist<20&&i.tick%90===89){c.push({kind:'spawn',prefabId:'drone-shot',position:{x:e.x+dx/dist*0.8,y:e.y+dy/dist*0.8,z:e.z+dz/dist*0.8},rotation:up(dx/dist,dy/dist,dz/dist)});cue('zap','drone-shot');c.push({kind:'rayQuery',queryId:'enemy-fire',origin:{x:e.x+dx/dist*0.8,y:e.y+dy/dist*0.8,z:e.z+dz/dist*0.8},direction:{x:dx,y:dy,z:dz},maxDistance:Math.max(0.1,dist-1.1)});}}
 }
 if(i.justPressed.includes('r')&&s.ammo<18&&s.reload===0){s.reload=i.tick+72;c.push({kind:'emit',event:'reload'});}
 if(s.reload>0&&i.tick>=s.reload){s.ammo=18;s.reload=0;}
 if(s.hp>0&&!s.won){
  const x=i.axes.moveX||0,z=i.axes.moveZ||0;
  c.push({kind:'characterIntent',movement:{x:x*Math.cos(s.yaw)+z*Math.sin(s.yaw),y:0,z:-x*Math.sin(s.yaw)+z*Math.cos(s.yaw)},jump:i.justPressed.includes('jump')});
  if(i.pressed.includes('fire')&&s.ammo>0&&s.reload===0&&i.tick>=s.nextShot){
   s.ammo--;s.nextShot=i.tick+9;c.push({kind:'emit',event:'shot'},{kind:'rayQuery',queryId:'rifle',origin:{x:i.entity.position.x,y:i.entity.position.y+0.65,z:i.entity.position.z},direction:{x:-Math.sin(s.yaw)*Math.cos(s.pitch),y:Math.sin(s.pitch),z:-Math.cos(s.yaw)*Math.cos(s.pitch)},maxDistance:70});
  }else if(i.pressed.includes('fire')&&s.ammo===0&&s.reload===0&&i.tick>=s.dry){s.dry=i.tick+20;c.push({kind:'emit',event:'dry'});}
  if(s.kills===5&&i.entity.position.z < -29){s.won=true;s.sting=i.tick+1;c.push({kind:'emit',event:'victory'});}
 }else{c.push({kind:'characterIntent',movement:{x:0,y:0,z:0},jump:false});}
 if(s.sting===i.tick){c.push({kind:'emit',event:'sting'});}
 const ui=(id,f)=>{const k=JSON.stringify(f);if(s.ui[id]!==k){s.ui[id]=k;c.push(Object.assign({kind:'ui',id},f));}};
 c.push({kind:'hud',id:'score',text:'',x:0,y:0});
 ui('objective',{text:s.won?'OPERATION COMPLETE':s.kills===5?'REACH THE EXTRACTION GATE':'ELIMINATE SECURITY DRONES'});
 ui('objective-count',{text:s.won?'':s.kills===5?'REACTOR SECURED':s.kills+' / 5'});
 ui('hp-value',{text:String(s.hp)});
 ui('hp-bar',{value:s.hp});
 ui('ammo-value',{text:String(s.ammo).padStart(2,'0')});
 ui('ammo-bar',{value:s.ammo});
 ui('weapon',{text:s.reload?'RELOADING':s.ammo===0?'EMPTY  /  PRESS R':'AR-09  PULSE RIFLE'});
 ui('hitmarker',{visible:s.hit>i.tick});
 ui('damage',{visible:s.damage>i.tick});
 ui('warning',{text:s.damage>i.tick?'INCOMING FIRE':s.charge>i.tick?'DRONE CHARGING':'',visible:s.damage>i.tick||s.charge>i.tick});
 ui('banner',{visible:s.won||s.hp===0});
 ui('help',{visible:i.tick<360});
 ui('banner-title',{text:s.won?'SECTOR CLEAR':s.hp===0?'SIGNAL LOST':''});
 ui('banner-sub',{text:s.won?'EXTRACTION COMPLETE':s.hp===0?'PRESS RESET TO REDEPLOY':''});
 return {state:s,commands:c};
}

(i)=>{const s=i.state||{yaw:0,pitch:0,kick:0,shake:0};
 s.yaw-=i.look.x*0.002;s.pitch=Math.max(-1.3,Math.min(1.3,s.pitch-i.look.y*0.002));
 for(const e of i.events){if(e.kind==='trigger'){if(e.event==='shot'){s.kick+=0.012;}if(e.event==='hurt'){s.shake=16;}}}
 s.kick*=0.8;const k=s.shake>0?0.014*s.shake/16:0;if(s.shake>0){s.shake--;}
 const yaw=s.yaw+k*Math.cos(i.tick*1.7),pitch=s.pitch+s.kick+k*Math.sin(i.tick*2.3),roll=k*0.6*Math.sin(i.tick*1.1);
 const m=(a,b)=>[a[3]*b[0]+a[0]*b[3]+a[1]*b[2]-a[2]*b[1],a[3]*b[1]-a[0]*b[2]+a[1]*b[3]+a[2]*b[0],a[3]*b[2]+a[0]*b[1]-a[1]*b[0]+a[2]*b[3],a[3]*b[3]-a[0]*b[0]-a[1]*b[1]-a[2]*b[2]];
 const q=m(m([0,Math.sin(yaw/2),0,Math.cos(yaw/2)],[Math.sin(pitch/2),0,0,Math.cos(pitch/2)]),[0,0,Math.sin(roll/2),Math.cos(roll/2)]);
 return{state:s,commands:[{kind:'setVisual',rotation:q}]};}

(i)=>{const s=i.state||{kick:0,sx:0,sy:0,reload:0,bob:0};
 for(const e of i.events){if(e.kind==='trigger'){if(e.event==='shot'){s.kick=0.09;}if(e.event==='reload'){s.reload=i.tick+72;}}}
 s.kick*=0.6;
 const cl=(v)=>Math.max(-0.05,Math.min(0.05,v));
 s.sx=cl(s.sx*0.85+i.look.x*0.0004);s.sy=cl(s.sy*0.85+i.look.y*0.0004);
 const mv=Math.min(1,Math.hypot(i.axes.moveX||0,i.axes.moveZ||0));s.bob+=mv*0.17;
 let rp=0,rr=0;if(s.reload>i.tick){const t=1-(s.reload-i.tick)/72,w=Math.sin(Math.PI*Math.min(1,t*1.25));rp=-0.28*w;rr=0.35*w;}
 const pitch=s.kick+rp+s.sy+Math.abs(Math.sin(s.bob))*0.014*mv,yaw=-s.sx+Math.sin(s.bob)*0.012*mv,roll=rr-s.sx*0.6;
 const m=(a,b)=>[a[3]*b[0]+a[0]*b[3]+a[1]*b[2]-a[2]*b[1],a[3]*b[1]-a[0]*b[2]+a[1]*b[3]+a[2]*b[0],a[3]*b[2]+a[0]*b[1]-a[1]*b[0]+a[2]*b[3],a[3]*b[3]-a[0]*b[0]-a[1]*b[1]-a[2]*b[2]];
 const q=m(m([0,Math.sin(yaw/2),0,Math.cos(yaw/2)],[Math.sin(pitch/2),0,0,Math.cos(pitch/2)]),[0,0,Math.sin(roll/2),Math.cos(roll/2)]);
 return{state:s,commands:[{kind:'setVisual',rotation:q}]};}
